"""
Use Case: Get task results (list of generated questions for a task).
Returns generation_source per question and warning when relevant.
"""

import uuid

from sqlalchemy.ext.asyncio import AsyncSession

from app.core.exceptions import NotFoundError
from app.core.logging import get_logger
from app.domain.enums import TaskStatus
from app.infrastructure.db.repositories import (
    GeneratedQuestionRepository,
    GenerationRequestRepository,
    GenerationTaskRepository,
)

logger = get_logger(__name__)

_FALLBACK_WARNING = (
    "Gemini quota exceeded. Questions were generated by local CPU fallback "
    "and local fallback quality is limited and requires manual review."
)


class GetTaskResultsUseCase:
    def __init__(self, db: AsyncSession) -> None:
        self.db = db
        self.task_repo = GenerationTaskRepository(db)
        self.req_repo = GenerationRequestRepository(db)
        self.q_repo = GeneratedQuestionRepository(db)

    async def execute(self, task_id: uuid.UUID) -> dict:
        """
        Fetch task status and all generated questions.

        Returns:
            dict with task_id, status, questions list, optional warning, and
            optional fewer_than_requested boolean.
        """
        task = await self.task_repo.get_by_id(task_id)
        if not task:
            raise NotFoundError("Task", str(task_id))

        questions = await self.q_repo.get_by_task_id(task_id)

        questions_out = []
        for index, q in enumerate(questions, start=1):
            display_order = getattr(q, "display_order", None) or index
            questions_out.append(
                {
                    "id": q.id,
                    "question_number": display_order,
                    "question_label": f"Câu {display_order}",
                    "question_content": q.question_content,
                    "options": {
                        "A": q.option_a,
                        "B": q.option_b,
                        "C": q.option_c,
                        "D": q.option_d,
                    },
                    "correct_answer": q.correct_answer,
                    "difficulty": q.difficulty,
                    "topic": q.topic,
                    "explanation": q.explanation,
                    "status": q.status,
                    "generation_source": getattr(q, "generation_source", "gemini"),
                }
            )

        # Determine warning
        warning = None
        if task.status == TaskStatus.COMPLETED_WITH_LOCAL_FALLBACK.value:
            warning = _FALLBACK_WARNING

        error_message = None
        if task.status == TaskStatus.FAILED.value:
            error_message = (getattr(task, "error_message", None) or "").strip() or None
            if error_message is None:
                request = await self.req_repo.get_by_id(task.request_id)
                error_message = (
                    (getattr(request, "error_message", None) or "").strip()
                    if request
                    else None
                ) or None

        # Warn if Gemini returned fewer questions than requested
        requested_qty = int(getattr(task, "number_of_questions", 0) or 0)
        actual_qty = len(questions_out)
        if (
            task.status == TaskStatus.COMPLETED.value
            and requested_qty > 0
            and actual_qty < requested_qty
        ):
            fewer_warning = (
                f"Generated {actual_qty}/{requested_qty} requested questions "
                "after validation and deduplication. The remaining questions "
                "were removed or not generated to preserve quality."
            )
            warning = fewer_warning if warning is None else f"{warning} {fewer_warning}"

        logger.info(
            "Fetched %d/%d questions for task=%s status=%s",
            actual_qty,
            requested_qty,
            task_id,
            task.status,
        )
        return {
            "task_id": task_id,
            "status": task.status,
            "warning": warning,
            "error_message": error_message,
            "questions": questions_out,
        }
